#!/bin/zsh
# Writes Config/Local.local.xcconfig from the running local Supabase stack (`supabase start` first).
set -euo pipefail
cd "${0:A:h}/.."

typeset -A env
while IFS='=' read -r key value; do
  env[$key]=${value//\"/}
done < <(supabase status -o env 2>/dev/null)

: "${env[API_URL]:?Local Supabase is not running. Run: supabase start}"
: "${env[ANON_KEY]:?supabase status did not report ANON_KEY}"

cat > Config/Local.local.xcconfig <<EOF
// Generated by scripts/write-local-config.sh. Not committed.
SUPABASE_URL = ${env[API_URL]/:\/\//:/\$()/}
SUPABASE_ANON_KEY = ${env[ANON_KEY]}
EOF
echo "Wrote Config/Local.local.xcconfig for ${env[API_URL]}"
